/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:padding:set:bottom' );


// MAIN //

/**
* Sets the bottom padding (in pixels).
*
* @private
* @param {number} value - input value
* @throws {TypeError} must be a number
* @returns {void}
*/
function set( value ) {
	if ( !isNumber( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a number. Value: `%s`.', 'bottom', value ) );
	}
	if ( value !== this._bottom ) {
		debug( 'Current value: %s. New value: %s.', this._bottom, value );
		this._bottom = value;
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
